Artifact 8: کد تولیدشده نهایی

این کد نهایی OrderService است که پس از AI Transformation و Human Review پذیرفته شده است. هر بخش دارای کامنت است که نشان می‌دهد از کدام قسمت Specification آمده است. این نگاشت در Traceability Matrix به‌صورت صریح ثبت می‌شود. کد، نه فقط کار کند، بلکه باید قابل دفاع باشد.

TYPESCRIPT
import { db } from '@/lib/db';
import { OrderStatus } from '../domain/order-status';
import { OrderValidator } from './order.validator';
import { EventPublisher } from '@/lib/events';
import { audit } from '@/lib/audit';
import { OrderError } from '../domain/errors';

export class OrderService {
  constructor(
    private readonly validator: OrderValidator,
    private readonly events: EventPublisher,
  ) {}

  /**
   * Implements FR-06 (Order Validation) + UC-04.
   * Source: spec FR-06.yaml, sequence SD-04.
   */
  async createOrder(input: CreateOrderInput): Promise<Order> {
    // TR-003 mod: idempotency check (added in human review)
    if (input.idempotencyKey) {
      const existing = await db.orders.findByIdempotencyKey(
        input.idempotencyKey,
      );
      if (existing) return existing;
    }

    // Run all FR-06 rules (R-01 to R-04)
    const result = await this.validator.validate(input);
    if (!result.ok) {
      throw new OrderError(result.reasonCode, result.message);
    }

    // TR-003 mod: wrap in transaction (atomicity)
    return db.transaction(async (tx) => {
      // Reserve wallet balance (rule R-01)
      await tx.wallets.reserve(
        input.studentId,
        result.totalAmount,
      );

      // Increment vendor capacity (rule R-02)
      await tx.vendors.incrementTodayOrders(
        input.vendorId,
        input.items.reduce((s, i) => s + i.quantity, 0),
      );

      // Persist order with PENDING status
      const order = await tx.orders.create({
        studentId: input.studentId,
        vendorId: input.vendorId,
        status: OrderStatus.PENDING,
        totalAmount: result.totalAmount,
        pickupTime: input.pickupTime,
        idempotencyKey: input.idempotencyKey,
        items: input.items,
      });

      // Side effects: audit + event
      await audit.append({
        entityType: 'Order',
        entityId: order.id,
        action: 'ORDER_PLACED',
        actorId: input.studentId,
      });

      this.events.emit('ORDER_PLACED', { orderId: order.id });
      return order;
    });
  }
}
