نمونه Test برای FR-06 Rule R-01
TYPESCRIPT
import { describe, it, expect } from 'vitest';
import { OrderValidator } from './order.validator';

describe('FR-06 / Rule R-01: wallet_balance_sufficient', () => {
  it('rejects order when wallet balance < total', async () => {
    const validator = new OrderValidator(mockDb({
      walletBalance: 5000,         // 50 Toman
      menuItemPrice: 2000,          // 20 Toman each
      vendorCapacity: 100,
    }));

    const result = await validator.validate({
      studentId: 's1',
      vendorId: 'v1',
      items: [{ menuItemId: 'm1', quantity: 3 }],  // 60 > 50
      pickupTime: '2025-01-01T12:00:00Z',
    });

    expect(result.ok).toBe(false);
    expect(result.reasonCode).toBe('INSUFFICIENT_BALANCE');
  });

  it('accepts order when wallet balance = total (boundary)', async () => {
    const validator = new OrderValidator(mockDb({
      walletBalance: 6000,
      menuItemPrice: 2000,
      vendorCapacity: 100,
    }));

    const result = await validator.validate({
      studentId: 's1', vendorId: 'v1',
      items: [{ menuItemId: 'm1', quantity: 3 }],
      pickupTime: '2025-01-01T12:00:00Z',
    });

    expect(result.ok).toBe(true);
  });
});
